!function(){"use strict";const e={"main-falls":{title:"Main Smoke Cascade (Hogenakkal)",sub:"Primary 20m Multi-Stream Plunge",desc:"Where the Kaveri River narrows through carbonatite bedrock and drops 20 meters. The sheer impact generates perpetual vapor clouds resembling smoke (Hoge), giving the falls its historic name.",loc:"Pennagaram Taluk, Dharmapuri District",river:"Kaveri River (Cauvery)",high:"Smoking mist, deep cylindrical potholes, roaring sound"},"coracle-jetty":{title:"Parisal Coracle Launch Jetty",sub:"Traditional Circular Bamboo Boat Hub",desc:"The designated TTDC boarding wharf where licensed coracle pilots guide circular bamboo and hide boats into the gorge, offering close-up encounters with misty side-streams.",loc:"Hogenakkal Riverfront Pier",river:"Lower Kaveri Gorge Channel",high:"Parisal navigation, water-level photography, spinning ride"},"cine-falls":{title:"Cine Falls & Rock Canyon",sub:"Deep Vertical Gorge & Film Heritage",desc:"A vertical rock amphitheater made world-famous by Indian cinema directors. Features sheer carbonatite cliff faces and secluded water coves only accessible via coracle.",loc:"Downstream Kaveri Canyon",river:"Mid-Gorge Chasm",high:"Cinematic gorge walls, ancient rock strata, serene coves"},"hanging-bridge":{title:"Suspension Hanging Bridge & Watchtower",sub:"High-Elevation Aerial Observation Platform",desc:"A suspension footbridge spanning across the roaring stream, allowing visitors to walk directly above the turbulent Kaveri channels and capture panoramic photographs.",loc:"Gorge Crossing Ridge",river:"Overlooking Primary Falls Network",high:"360-degree gorge views, secure pedestrian railing"},melagiri:{title:"Melagiri Forest Hills",sub:"Eastern-Western Ghats Ecological Corridor",desc:"Dense deciduous forests encompassing the waterfall valley, home to wild elephant herds, medicinal shrub flora, and rich biodiversity bordering Karnataka and Tamil Nadu.",loc:"Melagiri Wildlife Sanctuary Range",river:"Kaveri Catchment Basin",high:"Elephant corridor, medicinal plants, birdwatching"}},t={"post-monsoon":{title:"Post-Monsoon Peak & Coracle Safaris (October – February)",desc:"The ideal time to explore Hogenakkal. River flow is robust yet calm enough for licensed parisal (coracle) boat rides to navigate through the deep gorge. Weather is pleasant, fish markets are vibrant, and all viewpoints and footbridges are accessible.",flow:"Flow: Moderate, Crystal & Roaring",boat:"Boating: 100% Operational (Full Gorge Circuit)",highlight:"Highlights: Parisal rides, Oil massage & Fresh river fish"},monsoon:{title:"Heavy Monsoon Inflow (July – September)",desc:"During intense Southwest Monsoon releases from upstream Karnataka dams (KRS & Kabini), the Kaveri swells dramatically. Water covers entire rock ledges in an awe-inspiring deluge. Coracle rides are suspended for safety.",flow:"Flow: Extremely High Torrents & Surging Rapids",boat:"Boating: Suspended for public safety",highlight:"Highlights: Monumental roaring spectacle & hanging bridge views"},summer:{title:"Summer Placid Pools & Geological Study (March – May)",desc:"Water volume subsides, exposing the billion-year-old carbonatite rock beds, deep cylindrical erosion potholes, and gentle rock pools suitable for peaceful foot dipping and scientific examination.",flow:"Flow: Gentle Clear Streams",boat:"Boating: Partial shallow-water rides available",highlight:"Highlights: Carbonatite rock inspection & peaceful bathing"}};document.addEventListener("DOMContentLoaded",function(){const i=document.querySelectorAll(".river-pin"),a=document.getElementById("spot-title"),o=document.getElementById("spot-sub"),n=document.getElementById("spot-body"),r=document.getElementById("spot-loc"),s=document.getElementById("spot-river"),l=document.getElementById("spot-high"),c=document.querySelectorAll(".season-btn"),d=document.getElementById("s-card-title"),g=document.getElementById("s-card-desc"),h=document.getElementById("sp-flow"),m=document.getElementById("sp-boat"),u=document.getElementById("sp-highlight"),p=document.getElementById("theme-toggle");p&&p.addEventListener("click",function(){document.body.classList.toggle("light-theme");const e=document.body.classList.contains("light-theme");localStorage.setItem("theme",e?"light":"dark")}),i.forEach(function(t){t.addEventListener("click",function(){const i=t.getAttribute("data-spot"),c=e[i];c&&(a&&(a.textContent=c.title),o&&(o.textContent=c.sub),n&&(n.innerHTML=`<p>${c.desc}</p>`),r&&(r.textContent=c.loc),s&&(s.textContent=c.river),l&&(l.textContent=c.high))}),t.addEventListener("keydown",function(e){"Enter"!==e.key&&" "!==e.key||(e.preventDefault(),t.click())})}),c.forEach(function(e){e.addEventListener("click",function(){c.forEach(e=>e.classList.remove("active")),e.classList.add("active");const i=e.getAttribute("data-season"),a=t[i];a&&(d&&(d.textContent=a.title),g&&(g.textContent=a.desc),h&&(h.textContent=a.flow),m&&(m.textContent=a.boat),u&&(u.textContent=a.highlight))})});const b=document.getElementById("menu-toggle"),v=document.getElementById("nav-menu");b&&v&&b.addEventListener("click",()=>v.classList.toggle("active"))})}();